beforeSaveCustomScript:
// Format Windows License Key with dashes every 5 characters
if (windowsLicenceKey != '' && windowsLicenceKey != null) {
    // Remove existing dashes and spaces
    $cleaned = string\replace(string\replace(windowsLicenceKey, '-', ''), ' ', '');
    
    $length = string\length($cleaned);
    
    // Handle different common lengths
    if ($length == 15) {
        // 15 characters: XXXXX-XXXXX-XXXXX
        $part1 = string\substring($cleaned, 0, 5);
        $part2 = string\substring($cleaned, 5, 5);
        $part3 = string\substring($cleaned, 10, 5);
        windowsLicenceKey = string\concatenate($part1, '-', $part2, '-', $part3);
    } else if ($length == 20) {
        // 20 characters: XXXXX-XXXXX-XXXXX-XXXXX
        $part1 = string\substring($cleaned, 0, 5);
        $part2 = string\substring($cleaned, 5, 5);
        $part3 = string\substring($cleaned, 10, 5);
        $part4 = string\substring($cleaned, 15, 5);
        windowsLicenceKey = string\concatenate($part1, '-', $part2, '-', $part3, '-', $part4);
    } else if ($length == 25) {
        // 25 characters: XXXXX-XXXXX-XXXXX-XXXXX-XXXXX
        $part1 = string\substring($cleaned, 0, 5);
        $part2 = string\substring($cleaned, 5, 5);
        $part3 = string\substring($cleaned, 10, 5);
        $part4 = string\substring($cleaned, 15, 5);
        $part5 = string\substring($cleaned, 20, 5);
        windowsLicenceKey = string\concatenate($part1, '-', $part2, '-', $part3, '-', $part4, '-', $part5);
    } else if ($length > 5) {
        // Generic: add dashes every 5 characters
        $formatted = '';
        $i = 0;
        while ($i < $length) {
            $chunk = string\substring($cleaned, $i, 5);
            $formatted = string\concatenate($formatted, $chunk);
            $i = $i + 5;
            if ($i < $length) {
                $formatted = string\concatenate($formatted, '-');
            }
        }
        windowsLicenceKey = $formatted;
    }
}
